INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Istoriya Bomzha', 'Dive into the immersive world of Istoriya Bomzha (The Story of a Homeless Person), a unique third-person survival game where you embody a resourceful, albeit down-on-his-luck, homeless individual. Navigate the challenges of urban survival and experience a surprisingly cheerful story amidst the grit of the streets.' FROM games WHERE igdb_id = 368251 ON CONFLICT (game_id, language_code) DO NOTHING;
