INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kozue''s Strange Journey', 'Kozue’s Strange Journey is a turn-based RPG by Asakiyumemishi. The story follows university student Kozue Kato, who inadvertently stumbles into a world of shadowy monsters and teams up with the mysterious Sayuri Shirasagi to investigate a string of disappearances. The game features a classic JRPG combat system with enemy knockdown and bonus-turn mechanics, and is known for its eerie atmosphere and mature themes.' FROM games WHERE igdb_id = 156812 ON CONFLICT (game_id, language_code) DO NOTHING;
