INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Divine Invasion', 'The Divine Invasion is a science fiction adventure game where you play as a headhunter employed by mysterious masters, whose goals initially seem bizarre and surreal. It will all become clear, though, once our protagonist admits that while the technologies might be changing, the human heart is not. It is exactly the same as it was two thousand years ago.' FROM games WHERE igdb_id = 148689 ON CONFLICT (game_id, language_code) DO NOTHING;
