INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Loathe the Game', 'The Devil has a new minion! Condem sinners to hell all with the flick of the spacebar.Collect souls to power your soul meter and unlock evil upgrades to spawn more minions along the way.Each goal is something special to make the autoclicking expierience worthwhile and satisfying.This is one game that you surely want to miss.' FROM games WHERE igdb_id = 127533 ON CONFLICT (game_id, language_code) DO NOTHING;
