INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bubble Tower 3D', 'Bubble Tower 3D is a bubble shooter arcade game in which you have to destroy the colored balls in the cylinder-shaped area. This game comes with a cool Aztec theme! Try to connect at least 3 bubbles of the same color to destroy the spheres and reach the top of the tower. Not enough action? Try the destructive fireball and watch it work its magic. Reach the highest score.' FROM games WHERE igdb_id = 314478 ON CONFLICT (game_id, language_code) DO NOTHING;
