INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TRT Bil Bakalım', 'TRT Bil Bakalım is an educational trivia contest that appeals to everyone, featuring reliable and high-quality questions carefully prepared by experts. It has a vast question pool consisting of 8 main categories and 49 subcategories, including sports, geography, science, history, art, cinema/TV, general knowledge, and mixed. The entertaining trivia contest TRT Bil Bakalım offers the opportunity to play individual and head-to-head competitions, as well as with your friends by creating private rooms.' FROM games WHERE igdb_id = 380637 ON CONFLICT (game_id, language_code) DO NOTHING;
