INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kirakira-stars-idol-project-ai', 151604, '2020-02-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co59ah.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arck2.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirakira Stars Idol Project Ai', 'What if your childhood friend grew up into a gorgeous young lady? What if she asked you to move in with her? What if the two of you joined forces to make her the hottest new pop idol sensation? Follow fledgling idol Ai and producer Nobu as they navigate the ups and downs of life, love, and the entertainment industry in this visual novel adventure! -STORY- The entertainment industry is a battlefield. In recent years, countless pop idols have launched new careers, some achieving fame and fortune, others falling into obscurity. Competition is so fierce, people have started referring to this era as the "Warring Idols Period." Down on his luck and forced to leave his employee dorm, young producer Nobuyuki Kinoshita runs into an old friend, Ai Amane. Little does he know that this chance reunion will have far-reaching consequences. After inviting Nobuyuki to move in with her, and learning that his company is running low on talent, Ai makes a suprising declaration: "I want to be an idol!" Now, Ai is determined to help Nobu save ODA Productions from bankruptcy, and to transform her own life on the path to becoming an idol.' FROM games WHERE igdb_id = 151604 ON CONFLICT (game_id, language_code) DO NOTHING;
