INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vagrant.exe', 'There is strange feedback from this derelict office. Its wall full of faint echoes that whisper a sedated memory of normalcy. Articles artifacts and relics of slaves in white collars now lost to a stasis in time. There are other things to discover, if one is brave enough to see it through... you are the Vagrant.exe.' FROM games WHERE igdb_id = 249638 ON CONFLICT (game_id, language_code) DO NOTHING;
