INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lightless: The 21st Sacrifice', 'Lightless: The 21st Sacrifice is created in the style of point and click adventures from the early 2000s, and it offers a story-driven experience with puzzle-solving through an eerie atmosphere. The game uses unique in-game mechanics like the digital camera or the flashlight to emphasize the horror atmosphere and keeps creating suspense and a sense of discomfort.' FROM games WHERE igdb_id = 135482 ON CONFLICT (game_id, language_code) DO NOTHING;
