INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PGA Tour 2K21: Digital Deluxe Edition', 'The Digital Deluxe Edition includes the Golden Touch Pack featuring a gold-plated driver and gold-plated putter, as well as the 2K/adidas CodeChaos MyPlayer Pack featuring the adidas CodeChaos BOA Golf Shoes, and custom adidas / 2K CodeChaos Polo, Pants and Hat, designed by adidas, exclusively for PGA Tour 2K21. Players will also receive an additional 2300 currency to unlock additional MyPlayer gear to hit the links in style!' FROM games WHERE igdb_id = 164831 ON CONFLICT (game_id, language_code) DO NOTHING;
