INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pluto''s Ascent: Celestial Card', 'Compete in a cosmic tournament as the outcast god, Pluto, in a quest to redeem your honor as a true planet. Face other cosmic deities in card based RPG combat, grow your set of celestial skills, and face your destiny in the ultimate battle against Sol himself. Can you play your cards right and reclaim your spot as a true planet?' FROM games WHERE igdb_id = 395515 ON CONFLICT (game_id, language_code) DO NOTHING;
