INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drag Sim 2020', 'Drag Sim 2020 is the latest race simulator that will immerse you in the drag racing world! Enjoy driving over 70 spectacular cars, get under the hood with performance upgrades , customize your vehicle''s paint, wheels and calipers, create unique racing machines! Awesome features like the interior view, manual transmission, next-gen graphics and real time online multiplayer racing! Unlimited gameplay with no fuel required, 7 car tiers to choose from, supercars, exotics, vans, pickup trucks, legendary. Many different racing conditions are waiting for you. Show off your racer skills, become the best driver in the world!' FROM games WHERE igdb_id = 147741 ON CONFLICT (game_id, language_code) DO NOTHING;
