INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Koshka''s Kofe', 'After inheriting her estranged father’s coffee shop following his death, Catarina Koshka returns to her hometown to try to find closure. In this somber but heartwarming visual novel, players will make coffee, meet cute animal characters, and navigate the encroaching advances of a predatory corporation bent on buying out your neighborhood shop.' FROM games WHERE igdb_id = 135683 ON CONFLICT (game_id, language_code) DO NOTHING;
