INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SGS Afrika Korps', 'The game recreates the campaigns and battles of Erwin ‘Desert Fox’ Rommel’s legendary Afrika Korps, in Libya between 1941 and 1942. Play the Axis forces to conquer the most valuable prize of all: the Suez Canal. Or command the 8th Army soldiers, the famous Desert Rats, to repel the invaders.' FROM games WHERE igdb_id = 161542 ON CONFLICT (game_id, language_code) DO NOTHING;
