INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paranoihell', 'Paranoihell is a pixel horror game that takes inspiration from the gameplay of PSX-style survival horror games. Use weapons to defend yourself from enemies, set traps, or hide. But don''t be reckless, your resources are limited. Thorough exploration and careful item management will be key to survival.' FROM games WHERE igdb_id = 123826 ON CONFLICT (game_id, language_code) DO NOTHING;
