INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darius: Extra Version', 'While never originally ported to the Sega Genesis, a port of the game by M2 is featured on the Sega Genesis Mini microconsole of September 19th, 2019. Later, an expanded version titled "Darius Extra Version" was released for a Sega Mega Drive/Genesis cart for a special Amazon prime Day release on October 13th, 2020.
