INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Eye of the Beholder', 'Step into war-torn enemy territory in this immersive VR game experience based on the Oscar-shortlisted documentary MY ENEMY, MY BROTHER (2015). EYE OF THE BEHOLDER is a 20 minute beta experience that subverts the war-game genre as players must choose to combat or collaborate with others.' FROM games WHERE igdb_id = 292686 ON CONFLICT (game_id, language_code) DO NOTHING;
