INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Porklike: Wurst Comes to Worst', 'Porklike is a classic, turn-based Roguelike with minimalist lo-fi aesthetic. Enter the tower of Wurstlord. Can you make it to the top and steal his legendary Kielbasa? 9 floors of dangerous traps and enemies await you. Only if you move carefully and master your character''s abilities will you become the champion of Porklike.' FROM games WHERE igdb_id = 134206 ON CONFLICT (game_id, language_code) DO NOTHING;
