INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kuso', 146743, '2020-04-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co59as.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1kel.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kuso', 'kuso is a challenging yet fair platformer with a simple aesthetic. You have the ability to run, jump, and leave your own checkpoint. Make your way through acid, long jumps, disappearing platforms, bouncers, giant saws, and much more in this dreadful mechanical world. If you''re looking for a game that''ll challenge your platforming skills, something excellent to listen to, and a game to master, kuso is the game for you. Features: • 41 Unique Levels • 26 Unlockable Achievements • 2 Player Local Race Mode, perfect for Tabletop or TV Mode • A soundtrack composed by James Bennett with music crafted for each level • Hidden secrets and collectibles to find • A dedicated Speedrun Mode for individual levels or level sets with stat breakdowns for easy screenshot sharing' FROM games WHERE igdb_id = 146743 ON CONFLICT (game_id, language_code) DO NOTHING;
