INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-chicos', 149175, '2020-11-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co42my.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aronr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Chicos', 'Juego en tercera persona para niños y padres. Es un pequeño mundo abierto donde los niños pueden aprender a emprender en pequeños negocios como la venta de limonadas, pasteles y también aprender sobre finanzas, con entretenidas misiones e importantes moralejas para la vida.' FROM games WHERE igdb_id = 149175 ON CONFLICT (game_id, language_code) DO NOTHING;
