INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bakugan: Champions of Vestroia', 'Bakugan: Champions of Vestroia is an all-new action role-playing game with an original story that expands on the hit TV series and brings the Bakugan universe to the Nintendo Switch for the very first time. The adventure takes players on the ultimate Bakugan journey as they befriend powerful creatures known as Bakugan, gear up and customize Bakugan teams for fiercely strategic battles, and master their skills to become the Champion of Vestroia. Players can also play online in head-to-head multiplayer.' FROM games WHERE igdb_id = 135828 ON CONFLICT (game_id, language_code) DO NOTHING;
