INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pokémon Daybreak', 'Pokémon Daybreak, a fangame made in Pokémon Essentials, introduces the enigmatic region ''Armira'', and is centralized around storytelling and challenging gameplay. The game is aesthetically beautiful and there are many unique locations you will encounter on your journey, such as a meteor crash site, a castle and a cherry blossom forest. Themes of exploitation, greed, and history are examined and lore is dotted all throughout the game. Take on the challenge of becoming Pokémon Champion in the all-embracing region of Armira!' FROM games WHERE igdb_id = 241389 ON CONFLICT (game_id, language_code) DO NOTHING;
