INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avoid Them: Breakthrough Gaming Arcade', 'Strange circles are falling from the sky! It looks like mega trouble! Who knows where they came from?! But it doesn''t matter! You just need to run for your life and avoid them! In the same way, some Christians argue so much, and it can get so heated that a lot of rude, harsh, and evil feelings can come up among them. When you see trouble like this, just like in this video game, run away and don''t get involved!' FROM games WHERE igdb_id = 146250 ON CONFLICT (game_id, language_code) DO NOTHING;
