INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'West of Dead', 'Step into the boots of the dead man William Mason and descend into the grim and gritty world of Purgatory in this fast-paced twin-stick shooter that''ll put your skills to test. Dodge behind cover as you try to outgun your enemies in the unknown procedurally generated hunting grounds. The Wild West has never been this dark.' FROM games WHERE igdb_id = 125625 ON CONFLICT (game_id, language_code) DO NOTHING;
