INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('night-hood-and-the-mysterious-traveller', 276780, '2020-10-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7dhd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scpj18.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Night, Hood and the Mysterious Traveller', 'The game follows a girl named Dust as she is sent on a quest to bring bread and pie to a nearby village by the name of Woodpine. On the way she meets a charismatic young traveler who offers to aid her on her journey. When they arrive to the village they quickly discover that the village is not as peaceful as it seems. Young children have gone missing in the village, one after the another, during the last few months and as a result the village is in disarray. Will Dust with the help of her newfound friend, solve the enigma surrounding the missing children or will the dark secret of the village of Woodpine be left forever shrouded in mystery?' FROM games WHERE igdb_id = 276780 ON CONFLICT (game_id, language_code) DO NOTHING;
