INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Queerskins: A love story', 'Queerskins: a love story is a 6DoF interactive virtual reality experience. In this emotionally-charged experience, you are seated in the back seat of a photo-realistic 1986 Cadillac, behind Sebastian''s parents, as they take a journey down a country road in rural Missouri. Get to know Sebastian through the drama unfolding in intimate proximity in the front seat as well as by interacting with a collection of Sebastian''s personal belongings including his diary. Was he a "disgrace" like his father says or a "good man" as his mother believes?' FROM games WHERE igdb_id = 159649 ON CONFLICT (game_id, language_code) DO NOTHING;
