INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Calico', 'Calico is a low stress day-in-the-life community-sim where you move to a town of magical girls and are given a harrowing yet adorable task: make the town''s cat café active and full of cuddly creatures again! You will journey to a small village of Magical Girls and other fantastical friends to fix up the cat cafe, as well as fill it with furniture, decorations, yummy pastries and most importantly cats!' FROM games WHERE igdb_id = 122345 ON CONFLICT (game_id, language_code) DO NOTHING;
