INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Salad Bar Tycoon', 'Look out, this awesome salad bar will soon become the best one in town! Become the manager of a salad bar and learn for yourself just how hard it can be. Be careful not to mix up your recipes! Upgrade your bar and make it beautiful! Find ingredients of the best quality! Then create the best salad bar in town! Customers are waiting in line, and you have to serve them as fast as you can. Give it your best and you might just make it!' FROM games WHERE igdb_id = 147924 ON CONFLICT (game_id, language_code) DO NOTHING;
