INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Art Puzzle', 'Welcome to Art Puzzle - a special type of relaxing puzzle games that offers you the ultimate aesthetic experience. It is a unique place where anti-stress meets jigsaw puzzle-games. Solve picture puzzles, explore beautiful landscapes and admire dreamy imagery. Try this refreshing reimagination of jigsaw puzzles and art games for free!' FROM games WHERE igdb_id = 354421 ON CONFLICT (game_id, language_code) DO NOTHING;
