INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('forest-guardian--1', 147859, '2020-03-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3a1h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbl0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forest Guardian', 'What would you do if you met a fox girl in a forest? After collapsing in a forest while trying to make it to the local port before winter sets in, a lone merchant, Anna, wakes up in a pristine shrine. It doesn''t appear as though anybody else is there, with the exception of the caretaker, a kitsune who introduces herself as Mayu. Being the guardian of the forest, Mayu laments the fact that, with the exception of Anna, she has not had any visitors to her shrine in many, many years. Yet duty calls, and she is a very diligent fox girl. As thanks for saving her, Anna wants to help Mayu bring visitors back to her shrine, but what she learns in the meantime may end up making her change her mind. Confronted with Mayu''s past, what will Anna do?' FROM games WHERE igdb_id = 147859 ON CONFLICT (game_id, language_code) DO NOTHING;
