INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saboteur SiO', 'Saboteur SiO is the official sequel to the classic retro games Saboteur! and Saboteur II: Avenging Angel. Travel the world in this original ninja mission, created and developed by the original author, Clive Townsend. In 1985 Saboteur! received the prestigious award "The Crash Smash" from Crash magazine and was high-rated with a 93% score. In 1987 Clive made the sequel Saboteur II: Avenging Angel - the first video game to feature a female protagonist - Nina - sister of the ninja from the first game.' FROM games WHERE igdb_id = 147702 ON CONFLICT (game_id, language_code) DO NOTHING;
