INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lovely-fox', 102918, '2020-08-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co45h0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ark6h.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lovely Fox', 'Lovely Fox is a game that explores the adventures of a charming fox and her companions in the forest. This game allows players to accompany Lovely Fox on her journey as she navigates choices about lending a helping hand to fellow animals. Additionally, players can take on the responsibility of caring for Lovely Fox''s beloved elderly grandfather. Embrace the spirit of kindness and contribute to the flourishing of others in this endearing game.' FROM games WHERE igdb_id = 102918 ON CONFLICT (game_id, language_code) DO NOTHING;
