INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Pedestrian', 'The Pedestrian is a 2.5D puzzle platformer that takes "puzzle platforming" literally. You play as The Pedestrian (aka the male bathroom symbol) who works in a restroom sign standing beside his Beloved (the female symbol). When she disappears, you must escape your day job and embark on a perilous journey where you progress by piecing the "sign world" back together in search of the one you love.' FROM games WHERE igdb_id = 25837 ON CONFLICT (game_id, language_code) DO NOTHING;
