INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shell Song', 'Shell Song is an interactive audio-narrative game about deep-fake voice technologies and the datasets that go into their construction. By considering physical and digital bodies and voices, it asks what a voice is worth, who can own a human sound, and how it feels to come face to face with a ghost of your body that may yet come to outlive you.' FROM games WHERE igdb_id = 239384 ON CONFLICT (game_id, language_code) DO NOTHING;
