INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beneath Steel Clouds', 'Beneath Steel Clouds is a life-sim set in a dystopian future with a cyberpunk aesthetic and themes but without the gritty, grim-dark tone and with a healthy dose of snark added on top. You have thirty days to get a grip on your life, earn (or get) some credits and hopefully get the girl. Get on it, chummer, things ain’t gonna solve themselves! They never do.' FROM games WHERE igdb_id = 177625 ON CONFLICT (game_id, language_code) DO NOTHING;
