INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('awakening-of-cthulhu', 147769, '2020-09-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4e68.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1e1f.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Awakening of Cthulhu', 'How can a day go so mad? This is the question that runs on our hero Walter’s mind who is a jobless ex-veteran and suffers from PTSD. On the top all, Cthulhu is rising again from his eternal sleep from the deepest shadows of Earth to bring the apocalypse. With Cthulu’s effect, his unstable conditions created a delusional world. Nothing will be the same anymore, especially from Walter’s eyes. Everyone became monsters born from a mind inspired from HP Lovecraft’s books. And Cthulhu calls you! Cthulhu wants you! Go through him! To answer the call of Cthulhu, walk on streets of the city and defend yourself against monsters which await hunting you down. How can a man keep his sanity straight in this delusional world? Let’s take the ticket of an adventure full of madness and discover the delusional world of Walter born from Cthulhu’s awakening. And think that those monsters are real or a mad man attacking people on the streets while living in his delusional hollow.' FROM games WHERE igdb_id = 147769 ON CONFLICT (game_id, language_code) DO NOTHING;
