INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mona and the Witch''s Hat Deluxe', 'Mona and the Witch''s Hat Deluxe is a homebrew game made for the Game Boy Color, and is a remake of the original Mona and the Witch''s Hat from 2018. This "Deluxe" or "DX" version of Mona and the Witch''s Hat features a brand new soundtrack, full color graphics, and new animations. It features the same four levels as the original version, and can be completed in about 20 minutes.' FROM games WHERE igdb_id = 230458 ON CONFLICT (game_id, language_code) DO NOTHING;
