INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy VII Remake', 'A modern reimagining of one of the most iconic games of all time, Final Fantasy VII Remake harnesses the very latest technology to recreate and expand Square Enix''s legendary RPG adventure for the current generation. Set in a post-industrial fantasy world that has fallen under the control of the shadowy Shinra Electric Power Company, take on the role of Cloud Strife - a mercenary and former member of Shinra''s elite Soldier unit - and team up with anti-Shinra organization Avalanche as they step-up their resistance.' FROM games WHERE igdb_id = 11169 ON CONFLICT (game_id, language_code) DO NOTHING;
