INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drink More Glurp', 'Drink More Glurp is a wacky physics, sports(ish), hot seat, party game. Aliens have copied our ''Earth'' games and have got it all slightly wrong. Sponsors will randomly take control of events and twist them to fit their agenda creating havoc for the athletes. Support for up to 20 players all from one controller.' FROM games WHERE igdb_id = 117180 ON CONFLICT (game_id, language_code) DO NOTHING;
