INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demon''s Souls', 'Entirely rebuilt from the ground up and masterfully enhanced, Demon''s Souls is a remake of the 2009 release that introduces the horrors of a fog-laden, dark fantasy land to a whole new generation of gamers. Those who’ve faced its trials and tribulations before, can once again challenge the darkness in stunning visual quality with incredible performance. The remake features improved graphics and animations, sound and lighting tweaks and a reimagining of many of the visual, musical and mechanical aspects of the original game.' FROM games WHERE igdb_id = 134606 ON CONFLICT (game_id, language_code) DO NOTHING;
