INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nonsense-asteroid', 134327, '2020-03-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co28gt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8ad1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nonsense Asteroid', 'Nonsense Asteroid is a mobile arcade space action game. Stranded in space, the player needs to control a damaged spaceship in an asteroid field. The objective of the game is to survive the longest by evading asteroids, space debris and other obstacles. With simple control mechanics, using only one button, the player must direct the ship through space, the ship constantly rotates on its own axis, following the direction you are pointing the moment you press or hold the command button. The longer you survive, the more difficult it gets and the music gets more intense.' FROM games WHERE igdb_id = 134327 ON CONFLICT (game_id, language_code) DO NOTHING;
