INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fire-and-water', 147997, '2020-11-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57nj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arb2h.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire & Water', 'Fire & Water is a game where you use the power of fire and water in order to solve various puzzles. Both Water Girl and Fire boy are working together to solve a vast range of different, exciting puzzles all the time. Controlling the two characters is very simple, and you must help Fire boy avoid water, while Water girl needs to avoid fire. There’s also black water that can kill both of them. You will need to use mirrors, elevators, wind machines, pulleys, black balls and a variety of other tools in order to complete these tasks. The faster you do that, the better it will be. Features: Impressive puzzle gameplay More than 30 maps to play through Use pulleys, wind machines and elevators Escape the maze and win' FROM games WHERE igdb_id = 147997 ON CONFLICT (game_id, language_code) DO NOTHING;
