INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('wakamarina-valley-new-zealand', 134521, '2020-05-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2c68.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arsan.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wakamarina Valley, New Zealand', 'The game is a short exploration/photography experience set in the idyllic forested landscape of the Wakamarina Valley, located near Queen Charlotte Sound on New Zealand''s South Island. This project started out as a showcase of my work in environment design, I wanted to create a realistic, densely forested scene using photoscanned 3d assets that could run smoothly in real-time. The environment was created in Unreal Engine 4 with heavy reference to photos taken at the location, You''ll encounter rocky riverbeds, dense forest paths, vast farmland and distant hills, a lot of which resemble the appearance of the real valley in NZ.' FROM games WHERE igdb_id = 134521 ON CONFLICT (game_id, language_code) DO NOTHING;
