INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('number-womenup-super-puzzles-dream', 147437, '2020-05-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4e2f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar92m.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '#womenUp, Super Puzzles Dream', 'Puzzles move onto the next level with ‘Super Puzzle Dream’, a mix between classic jigsaw and a ‘Tetris’-style dynamic mechanic. #womenUp! is the ''hashtag'' for this programme, which dedicates beautiful illustrations and emotive phrases to women on completion of every puzzle. Two levels of play, ''senior'' (for adults) and ''junior'' (for children aged 3+), guarantee hours of entertainment for all. Become an expert and finish the puzzles in the shortest possible time and you will find yourself amongst the best in the world on the online leaderboard. You can also play with friends and family in the one-on-one split-screen competition mode. Your rival won''t make it easy for you!' FROM games WHERE igdb_id = 147437 ON CONFLICT (game_id, language_code) DO NOTHING;
