INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('take-a-hike', 154729, '2020-09-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3db4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3jhm.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Take a Hike!', 'Cheerful slacker Olive thought that taking an outdoor ed. class during her final year of high school would be an easy credit, but the year-end camping trip turns out to be a lot more than she bargained for. When an argument with another classmate spurs the hot-tempered Sage to run off alone into the woods, Olive follows her, hoping to lift her spirits and make sure she’s safe. But the bubbly and energetic Heather has the same idea, and tensions between her and Sage threaten to turn the trip into even more of a disaster than it is already. Olive just wants her classmates to get along, but they seem to disagree on everything—and to make things even worse, they’ve lost track of how to get back to their campsite! Follow three stressed-out teens on a journey full of bickering, mosquitoes, and self-discovery.' FROM games WHERE igdb_id = 154729 ON CONFLICT (game_id, language_code) DO NOTHING;
