INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Borderlands 3: Ultimate Edition', 'Borderlands 3 Ultimate Edition is the quintessential Borderlands 3 experience, featuring the award-winning base game plus all six content add-ons and the full collection of bonus cosmetic packs! Blast through multiple worlds as one of four Vault Hunters – the ultimate treasure-seeking badasses of the Borderlands, each with deep skill trees, abilities, and customization. Play solo or join with friends to take on deranged enemies, score loads of loot, and save your home from the most ruthless cult leaders in the galaxy.' FROM games WHERE igdb_id = 140899 ON CONFLICT (game_id, language_code) DO NOTHING;
