INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcus', 'Arcus is a fantasy action game where failure is just the next step in the story. Use a bow to aim and fire arrows at invading enemies. Swing your sword at any angle to get past enemy defenses. Spend resources between missions to buy special arrow types and increase your chances of success while you solve the mystery behind the new undead skeleton faction in a land where magic has been made taboo.' FROM games WHERE igdb_id = 150901 ON CONFLICT (game_id, language_code) DO NOTHING;
