INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bokuhime Project', 'Bokuhime Project is a mystery adventure video game developed by Wizard Soft and published by Nippon Ichi Software. The player takes the role of a young man who infiltrates a school for refined young ladies by enrolling as a female student to investigate an incident involving his sister. As part of their investigation, the player aims to get a seat in an influential organization at the school, and thereby needs to improve their character statistics to raise their character''s cuteness, overcoming the other candidates.' FROM games WHERE igdb_id = 121199 ON CONFLICT (game_id, language_code) DO NOTHING;
