INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Landlord Go!', 'Landlord Go is the first tycoon game based on a real map of the United States and the world. It allows you to literally bring the gameplay into the real world. Buy, sell, and upgrade real buildings that you encounter every day on your way to work or school. From grand and famous landmarks to local shops and businesses.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 235293 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
