INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neon Parasite', 'INFEST YOUR FRIENDS! Neon Parasite is a game of chaotic critter combat where you''ll be hovering, shooting, and dashing your way around the competition to reign the most infested bug of all. This 4-player local party game boasts crazy strategic battles across a multitude of different arenas.' FROM games WHERE igdb_id = 139347 ON CONFLICT (game_id, language_code) DO NOTHING;
