INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Puzzle Pack', 'Super Puzzle Pack brings together hundreds of unique puzzles played across 4 different puzzle types. Play with up to 4 players for hours of Jigsaw Fun. Enjoy two stunning hand-drawn match-3 games in a solo adventure. Challenge friends to a 1-vs-1 battle in the 2048 challenge, or in a unique match-5 game with a twist. • Complete over 200 unique jigsaw puzzles, solo or up to 4 players • Defeat all 100 levels of a beautifully hand-drawn match-3 pirate game • Solo or 1-vs-1 battles in the 2048 challenge, with local leaderboards • Adventure through a mystical match-3 game and save the Fuzzy family • Help the Yum Yums clear all the jelly in a new match-5 game' FROM games WHERE igdb_id = 139238 ON CONFLICT (game_id, language_code) DO NOTHING;
