INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('home-postmortem-edition', 146776, '2020-10-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57qj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcj9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Home: Postmortem Edition', 'Play the complete indie horror classic, now with a brand-new Postmortem Mode — a guided tour by the developer that brings you behind the scenes as you play the game! Awakened by an oncoming storm, you open your eyes to discover yourself in a strange, dark room — tucked away in a house that’s not yours. Find your way back home — but be careful, because each choice you make can change your story in ways you might not expect. FEATURES: - The complete, original indie horror classic, rebuilt for Nintendo Switch - Multiple endings and story variations, depending on your choices and actions - Innovative new Postmortem Mode provides a guided tour of how the game was made, as you play it — straight from the developer - New behind-the-scenes Gallery complete with design documents, process images and other creepy, real-world artifacts' FROM games WHERE igdb_id = 146776 ON CONFLICT (game_id, language_code) DO NOTHING;
