INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hero Allstars: Void Invasion', '용사 올스타즈: 공허의 습격(Hero Allstars: Void Invasion)은 캐주얼한 판타지 턴제 롤플레잉 게임입니다. 전 세계에 걸쳐 일어난 이상 현상을 조사하는 군대의 지휘관이 되어, 여러명의 동료들과 함께 진실을 파헤치며 다가오는 모든 적들을 쓰러뜨리세요.' FROM games WHERE igdb_id = 158120 ON CONFLICT (game_id, language_code) DO NOTHING;
