INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Circle Tank', 'Circle Tank is a one-button minimalist coffee-break tank action game. Through three acts, mash uncontrollably as an onslaught of cuboid enemies threaten your existence. Intentionally awkward controls make this a rage-inducing challenge that will put you to the test. Can you survive?' FROM games WHERE igdb_id = 138658 ON CONFLICT (game_id, language_code) DO NOTHING;
