INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pixboy', 'Pixboy is a 2D platformer in old-school colors that gives you the true retro vibes. There are 40 hand-crafted levels, 30 enemies, 150+ secret rooms, and 24 color themes resembling old devices from the previous century. Explore 4 different worlds with unique mechanics, fight with enemies (or show them mercy to get a special Pacifist Badge!), try to beat speedrun thresholds set by ruthless authors, listen to an original chiptune soundtrack and have fun! Use this game to travel back to the ''90s!' FROM games WHERE igdb_id = 135650 ON CONFLICT (game_id, language_code) DO NOTHING;
