INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('time-heist', 134093, '2020-02-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2797.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time Heist', 'You and your friends are part of teams of time travelers. Two teams compete with each other to reach their ultimate goal: the PARADOX THIEVES, who want to steal history''s most precious treasures, and the GUARDIANS OF TIME, who want to restore time and prevent its collapse. To play, both teams must choose players to be their respective captains; only the captains are allowed to look at the screen during the game. For each mission, the captains must look the century and category of the desired goal and tell the other players, who will try to guess what it is and win the goal for them. The captains must alternate giving clues about the object to their respective teams, but, after a clue is given, only the oposite team is allowed to guess. Each team may discuss and is allowed one guess per turn. The team who wins the goal is on step closer to conquering time. There are three types of game modes: Fast, Regular and Legend. In Fast mode, players compete for the best out of three missions, in Regular, for the best out of five of missions, and in Legend for the best out of seven missions.' FROM games WHERE igdb_id = 134093 ON CONFLICT (game_id, language_code) DO NOTHING;
