INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paraiso Island', 'Paraiso Island is a free-to-play island life sim. Explore a cheerful tropical island, meet wacky animal residents, help them with daily tasks, and decorate your own home with furnishings! Plant and harvest fruit, go fishing, or just relax and enjoy the scenery. Features a real-time day/night cycle, special events, and more surprises!
