INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pixels Out of Space', 'You are part of a scientific group that is in charge of studying a farm where strange events have happened since months ago. Day by day, the atmosphere becomes more and more strange, and you start losing the sense of time. Suddenly, you woke up in an empty room... But you feel that something that is not from this world is watching you.' FROM games WHERE igdb_id = 186253 ON CONFLICT (game_id, language_code) DO NOTHING;
