INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Destropolis', 'Destropolis is a top-down shooter game, inspired by such classic games like “Crimsonland”, “Alien Shooter” or “Nuclear Throne”. It takes place in a futuristic city, filled with red, cube-like enemies. Tear them to pieces with bullets, lasers and nuclear explosions. Play alone or with friends in a local co-op mode. Destroy as many enemies as you can before they overwhelm you.' FROM games WHERE igdb_id = 143587 ON CONFLICT (game_id, language_code) DO NOTHING;
