INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TurnTack', 'Monsters destroyed all of the human world. Half-blood girl who is the player in the game goes back to the world that it''s yet destroyed. She tries to keep the human world safe but the monsters have been suffering likewise. Therefore she is confused what''s right to do because of her half-blood identity.' FROM games WHERE igdb_id = 113084 ON CONFLICT (game_id, language_code) DO NOTHING;
