INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fatec''s Out', 'Fatec’s Out is an epic adventure that shows how a digital games professor has to protect the universe’s reality that’s being built beneath his feet. Being a game of the nostalgic and acclaimed Beat’em Up genre, it will make you remember what makes the most famous games of the 90’s timeless.' FROM games WHERE igdb_id = 132274 ON CONFLICT (game_id, language_code) DO NOTHING;
