INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '幻刃录', '《幻刃录》是一款西游题材的RPG仙侠游戏，不单拥有丰富的玩法、精美的场景、炫丽的打斗特效等特色，更有幻刃神兵特色养成系统；在游戏里你可将一块凡铁打造成为能与孙悟空金箍棒同阶的存在，幻刃神兵多种形态可满足玩家培养的欲望；游戏中更新悟空虎装，唐僧袈裟等特色时装让玩家本色出演；加入仙门学习仙法，丰富副本获得法宝，开局送神兵，通关送vip，元宝直接掉落，拥有VIP与神兵的你，可以创建家族，制霸全服；快来与孙悟空一起大闹天宫吧！' FROM games WHERE igdb_id = 158155 ON CONFLICT (game_id, language_code) DO NOTHING;
