INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lithium City', 'Lithium City is a stylized isometric action game set in a neon-drenched world of electricity and violence. Fight, shoot, and dash your way through the dark and vibrant world of Lithium City. Take on armed guards, erratic thugs, and mindless drones as you make your way higher and higher up the towering neon skyscrapers. At the highest point, your deadliest opponent awaits...' FROM games WHERE igdb_id = 134543 ON CONFLICT (game_id, language_code) DO NOTHING;
