INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slash Quest!', 'Forget your power fantasy. Slash Quest’s simple yet unfamiliar controls will put you in the shoes of an unlikely knight with a big heart, an even bigger weapon, and absolutely zero skills. But worry not! Just like Shep and Swordie’s friendship, before you know it everything will feel right and everyone will be counting on you to save the Queendom.' FROM games WHERE igdb_id = 171982 ON CONFLICT (game_id, language_code) DO NOTHING;
