INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Streets of Rage 4: Signature Edition', 'Streets of Rage 4 is an all-new continuation of the iconic arcade brawler series known for its radical fights, jammin’ ‘90s beats and dashing sparring gloves and bandanas. The Streets of Rage 4: Signature Edition includes a region free copy of the base game, five limited edition enamel pins, a numbered collector’s certificate, Axel Stone''s blue bandana, and the 2 CD full original soundtrack, as well as being packaged in a sturdy “Sierra” box with outer sleeve.' FROM games WHERE igdb_id = 136048 ON CONFLICT (game_id, language_code) DO NOTHING;
