INSERT INTO game_artwork (game_id, url, artwork_type, display_order, is_featured) SELECT id, 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1u65.jpg', 'promotional', 0, true FROM games WHERE igdb_id = 135739 ON CONFLICT DO NOTHING;